using System.Text.Json;
using System.IO.Compression;
using SimplePZMapmaker.Core;
using SimplePZMapmaker.Core.Export;
using SimplePZMapmaker.Web.Services;

public static class DeckArtworkTests
{
 const string Art="blends_street_01_16";
 static LinearFeature Feature(int z=0,string artwork="[{\"x\":50,\"y\":80,\"tile\":\"blends_street_01_16\"}]")=>JsonSerializer.Deserialize<LinearFeature>($$"""{"id":"painted-deck","kind":"bridge","level":{{z}},"width":4,"points":[{"x":40,"y":80},{"x":70,"y":80}],"deckArtwork":{{artwork}}} """,NativeMapExporter.JsonOptions)!;
 public static IEnumerable<(string,Action)> Cases(){
  yield return("deck artwork survives native composition without repainting underlying water",()=>{
   foreach(var z in new[]{0,2,-2}){var p=MapGenerator.Generate(new(){Kind="blank"});p.Terrain[80*256+50]=Terrain.Water;var n=LinearFeatureEditor.Put(p,Feature(z));var scene=NativeScene.Cell(n,48,78,5,5,z);Check(scene.Sprites.Any(s=>s.X==50&&s.Y==80&&s.Z==z&&s.Tile==Art),"Deck artwork disappeared");Check(scene.Sprites.Any(s=>s.X==50&&s.Y==80&&s.Z==z&&s.Tile==InfrastructureGeometry.DeckTile),"Artwork replaced the structural floor");Check(n.Terrain[80*256+50]==Terrain.Water&&n.SurfaceTiles.Count==0,"Artwork repainted source water");Check(NativeScene.ResourceIds(n).Contains(Art),"Artwork missing from resource dependencies");Check(n.Version==18,"Deck artwork needs map format 18");var restored=JsonSerializer.Deserialize<MapProject>(JsonSerializer.Serialize(n,NativeMapExporter.JsonOptions),NativeMapExporter.JsonOptions)!;Check(NativeScene.Cell(restored,48,78,5,5,z).Sprites.Any(s=>s.Tile==Art),"Save lost artwork");Check(!NativeScene.Cell(LinearFeatureEditor.Remove(n,"painted-deck"),48,78,5,5,z).Sprites.Any(s=>s.Tile==Art),"Removed deck left artwork behind");}
  });
  yield return("deck artwork rejects duplicates unsupported ground and positions outside its owner",()=>{
   var p=MapGenerator.Generate(new(){Kind="blank"});Reject(()=>LinearFeatureEditor.Put(p,Feature(0,"[{\"x\":10,\"y\":10,\"tile\":\"blends_street_01_16\"}]")));Reject(()=>LinearFeatureEditor.Put(p,Feature(0,"[{\"x\":50,\"y\":80,\"tile\":\"blends_street_01_16\"},{\"x\":50,\"y\":80,\"tile\":\"blends_street_01_16\"}]")));var f=Feature();f.Kind="road";Reject(()=>LinearFeatureEditor.Put(p,f));
  });
  yield return("shared deck artwork projects across a section seam at its own signed floor",()=>{
   var a=MapGenerator.Generate(new(){Kind="blank"});var b=MapGenerator.Generate(new(){Kind="blank"});a.WorldX=0;a.WorldY=0;b.WorldX=1;b.WorldY=0;var w=new WorldProject{Maps=[new(){Project=a},new(){Project=b}]};var f=JsonSerializer.Deserialize<LinearFeature>("""{"id":"shared-art","kind":"bridge","level":2,"width":4,"points":[{"x":240,"y":80},{"x":270,"y":80}],"deckArtwork":[{"x":255,"y":80,"tile":"blends_street_01_16"},{"x":256,"y":80,"tile":"blends_street_01_16"}]}""",NativeMapExporter.JsonOptions)!;var next=WorldInfrastructure.Put(w,f);Check(next.Version==13,"Deck artwork needs world format 13");foreach(var m in next.Maps){var p=WorldAssembler.ProjectSection(next,m);var x=p.WorldX==0?255:0;Check(NativeViewportScene.FromProject(p).Read(x==255?248:0,80,8,1,2).Sprites.Any(s=>s.X==x&&s.Y==80&&s.Z==2&&s.Tile==Art),"Section projection lost deck artwork");}
  });
  yield return("deck artwork native archive keeps original water navigation and exact layered square",()=>{
   var p=MapGenerator.Generate(new(){Kind="blank"});p.Terrain[80*256+50]=Terrain.Water;p=LinearFeatureEditor.Put(p,Feature());var before=JsonSerializer.Deserialize<MapProject>(JsonSerializer.Serialize(p,NativeMapExporter.JsonOptions),NativeMapExporter.JsonOptions)!;before.LinearFeatures[0].DeckArtwork.Clear();using var old=new ZipArchive(new MemoryStream(NativeMapExporter.Export(before)));using var next=new ZipArchive(new MemoryStream(NativeMapExporter.Export(p)));Check(AssetTests.NativeTiles(next,p,50,80,0).SequenceEqual(new[]{InfrastructureGeometry.DeckTile,Art}),"Native LOT lost ordered deck layers");foreach(var entry in old.Entries.Where(e=>e.Name.StartsWith("chunkdata_")||e.Name.StartsWith("biomemap_"))){using var a=new MemoryStream();entry.Open().CopyTo(a);using var b=new MemoryStream();next.GetEntry(entry.FullName)!.Open().CopyTo(b);Check(a.ToArray().SequenceEqual(b.ToArray()),"Artwork changed navigation or biomes");}
  });
  yield return("deck artwork cannot survive a shared stair hole through its supporting floor",()=>{
   var p=MapGenerator.Generate(new(){Kind="blank"});var f=Feature(2);f.Access="stairs";p=LinearFeatureEditor.Put(p,f);p.SharedInfrastructure=new([], [new(50,80,2)]);Reject(()=>InfrastructureGeometry.Validate(p));
  });
  yield return("deck artwork cannot masquerade as an original structural stair or rail resource",()=>{
   var f=Feature(1,"[{\"x\":50,\"y\":80,\"tile\":\"carpentry_02_98\"}]");f.Access="stairs";Reject(()=>LinearFeatureEditor.ValidateFeature(f));
  });
  yield return("shared deck artwork retains mod ownership and exports above water through saved sections",()=>{
   var root=Path.Combine(Environment.GetEnvironmentVariable("PZMAP_WORKSPACE")!,"work","deck-art-tests",Guid.NewGuid().ToString("N"));var game=Path.Combine(root,"game");Directory.CreateDirectory(Path.Combine(game,"media","texturepacks"));File.WriteAllText(Path.Combine(game,"media","newtiledefinitions.tiles.txt"),string.Join("\n",new[]{"blends_natural_01_32","blends_natural_02_0",InfrastructureGeometry.DeckTile}.Select(id=>$"// {id}\ntile\n{{\nsolidfloor =\n}}\n")));var mod=Path.Combine(root,"mods","fixture","42");Directory.CreateDirectory(Path.Combine(mod,"media"));File.WriteAllText(Path.Combine(mod,"mod.info"),"id=fixture_deck_mod\nname=Deck fixture\ntiledef=fixture_deck 1706\n");File.WriteAllBytes(Path.Combine(mod,"media","fixture_deck.tiles"),TilesetBuilder.Tiles("fixture_deck",[new(){["solidfloor"]=""}]));var assets=new GameAssetCatalog(Path.Combine(root,"workspace"),game);assets.DiscoverMods([Path.Combine(root,"mods")]);assets.ActivateMods(["fixture_deck_mod"]);
   var a=MapGenerator.Generate(new(){Kind="blank"});var b=MapGenerator.Generate(new(){Kind="blank"});a.WorldX=0;a.WorldY=0;b.WorldX=1;b.WorldY=0;a.Terrain[80*256+255]=Terrain.Water;b.Terrain[80*256]=Terrain.Water;var w=new WorldProject{Maps=[new(){Project=a},new(){Project=b}]};var f=JsonSerializer.Deserialize<LinearFeature>("""{"id":"shared-mod","kind":"bridge","width":4,"points":[{"x":240,"y":80},{"x":270,"y":80}],"deckArtwork":[{"x":255,"y":80,"tile":"fixture_deck_0"},{"x":256,"y":80,"tile":"fixture_deck_0"}]}""",NativeMapExporter.JsonOptions)!;w=WorldInfrastructure.Put(w,f);AssetRules.WorldInfrastructure(w,assets);Check(w.LinearFeatures[0].AssetSources.GetValueOrDefault("fixture_deck_0")=="fixture_deck_mod","Shared artwork provider was not saved");using(var zip=new ZipArchive(new MemoryStream(NativeWorldExporter.Export(w)))){using var reader=new StreamReader(zip.Entries.Single(e=>e.FullName.EndsWith("/42/mod.info")).Open());Check(reader.ReadToEnd().Contains("require=fixture_deck_mod"),"Loaded-world export omitted the shared resource mod");}
   using var store=new WorldStore(Path.Combine(root,"recovery"));store.SaveAsync(w.Id,w).GetAwaiter().GetResult();using(var lease=store.PinAsync(w.Id).GetAwaiter().GetResult()){var p=lease.ReadProjectedSectionAsync(w.Maps[0].Id).GetAwaiter().GetResult();Check(p.Terrain[80*256+255]==Terrain.Water&&p.AssetSources["fixture_deck_0"]=="fixture_deck_mod"&&ResourceDependencies.ForProject(p).Contains("fixture_deck_mod"),"Saved projection lost water or ownership");}
   var exporter=new NativeExportService(root);var result=(Microsoft.AspNetCore.Http.HttpResults.FileStreamHttpResult)exporter.Workspace(store.PinAsync(w.Id).GetAwaiter().GetResult(),assets,new StaticModelCatalog(assets),CancellationToken.None).GetAwaiter().GetResult();using(var zip=new ZipArchive(result.FileStream)){using var reader=new StreamReader(zip.Entries.Single(e=>e.FullName.EndsWith("/42/mod.info")).Open());Check(reader.ReadToEnd().Contains("fixture_deck_mod"),"Streamed workspace export omitted shared artwork dependency");}w.LinearFeatures[0].AssetSources["fixture_deck_0"]="wrong_mod";Reject(()=>AssetRules.WorldInfrastructure(w,assets));
  });
  yield return("deck artwork game rules reject water walls collision and stair floor resources",()=>{
   var root=Path.Combine(Path.GetTempPath(),"pz-deck-art",Guid.NewGuid().ToString("N"));var game=Path.Combine(root,"game");Directory.CreateDirectory(Path.Combine(game,"media","texturepacks"));File.WriteAllText(Path.Combine(game,"media","newtiledefinitions.tiles.txt"),"// deck_floor_0\ntile\n{\nsolidfloor =\n}\n// deck_wall_0\ntile\n{\nsolidtrans =\n}\n// deck_water_0\ntile\n{\nsolidfloor =\nwater =\n}\n// deck_collision_0\ntile\n{\nsolidfloor =\ncollideN =\n}\n// deck_stair_0\ntile\n{\nsolidfloor =\nstairsTN =\n}\n");var assets=new GameAssetCatalog(Path.Combine(root,"workspace"),game);AssetRules.CheckDeckArtwork(assets,"deck_floor_0");foreach(var id in new[]{"deck_wall_0","deck_water_0","deck_collision_0","deck_stair_0"})Reject(()=>AssetRules.CheckDeckArtwork(assets,id));
  });
 }
 static void Check(bool ok,string message){if(!ok)throw new Exception(message);}
 static void Reject(Action action){try{action();}catch(ArgumentException){return;}throw new Exception("Expected invalid deck artwork to be rejected");}
}
